CREATE TRIGGER universe_snapshot_market_guard_ins BEFORE INSERT ON universe_snapshot
WHEN NEW.market IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM market WHERE code = NEW.market AND enabled = 1)
BEGIN
  SELECT RAISE(ABORT, 'MarketNotEnabled universe_snapshot');
END;
CREATE TRIGGER universe_snapshot_market_guard_upd BEFORE UPDATE OF market ON universe_snapshot
WHEN NEW.market IS NOT NULL AND NEW.market IS NOT OLD.market
  AND NOT EXISTS (SELECT 1 FROM market WHERE code = NEW.market AND enabled = 1)
BEGIN
  SELECT RAISE(ABORT, 'MarketNotEnabled universe_snapshot');
END;

